_count","research_relevant"]},"work_experience":{"formula":"none_score + (100 - none_score) * min(effective_months / saturation_months, 1)；effective_months = work_months * company_factor[work_company_tier] * relevance_factor[work_relevant]；无经历时 effective_months = 0","company_factor":{"top":1.0,"normal":0.7},"relevance_factor":{"yes":1.0,"no":0.5},"none_score":20,"saturation_months":9,"saturation_months_by_field":{},"notes":"头部 / 一般、相关 / 不相关、累计月数来自设计文档 §1；问卷按整体采集（累计月数、是否在头部公司、是否相关）；系数与“满分所需月数”AI 草拟，需顾问确认","input":["work_months","work_company_tier","work_relevant"]},"other_soft":{"formula":"awards_level = none 时取 none_score；否则 min(100, level_score[awards_level] + extra_item_bonus * (awards_count - 1))","level_score":{"international":90,"national":75,"provincial":60,"school":45,"none":20},"none_score":20,"extra_item_bonus":5,"notes":"国际 / 国家 / 省级 / 校级来自设计文档 §1；分值 AI 草拟，需顾问确认","input":["awards_level","awards_count"]},"course_match":{"formula":"clamp(100 * course_match_ratio)","applies":false,"notes":"设计文档 §8（德国）：已对口学分 / 目标项目要求学分，由成绩单解析得到；映射方式 AI 草拟，需顾问确认","input":["course_match_ratio"]}},"hard_thresholds":{"source_priority":["program_requirement","defaults_below"],"on_fail":"needs_improvement","on_fail_label":"补足后可申","unverified_flag_when_default_used":true,"notes":"设计文档 §3：先按项目官网要求过滤，不达标的不进冲稳保，单列「补足后可申」。项目库（abr_requirement）有记录时只用项目库；下列默认值只在项目缺记录时兜底，并给结果打「要求待核实」标记","language":{"scale":"ielts_equivalent","defaults_by_difficulty":{"D1":{"overall":7.0,"min_sub":6.5},"D2":{"overall":6.5,"min_sub":6.0},"D3":{"overall":6.5,"min_sub":6.0},"D4":{"overall":6.0,"min_sub":5.5},"D5":{"overall":6.0,"min_sub":5.5}},"notes":"检查总分与小分（设计文档 §3）；托福 / 多邻国按官方对照表换算到雅思尺度（§1，归一化阶段完成）；兜底分值 AI 草拟，需顾问确认"},"min_gpa_by_undergrad_tier":{"defaults_by_difficulty":{"D1":{"c9":87,"985":89,"211":91,"double_first_class":92,"non_key":93,"overseas":83},"D2":{"c9":85,"985":87,"211":89,"double_first_class":90,"non_key":91,"overseas":81},"D3":{"c9":83,"985":85,"211":87,"double_first_class":88,"non_key":89,"ove