tier_base":{"c9":90,"985":82,"211":72,"double_first_class":68,"non_key":55,"overseas":70},"tier_base_notes":"分档方式来自设计文档 §1；分值 AI 草拟，需顾问确认","tier_reference_gpa":{"c9":80,"985":82,"211":84,"double_first_class":85,"non_key":86,"overseas":75},"tier_reference_gpa_notes":"设计文档 §1「院校层次对应的门槛均分」，按本国中游项目口径；数值 AI 草拟，需顾问确认（各校认可名单以官网为准）","gpa_slope":2.5,"gpa_slope_notes":"每高出门槛均分 1 分加的子分；AI 草拟，需顾问确认","rank_bonus":{"top10":3,"top30":1,"other":0,"null":0},"rank_bonus_notes":"排名档来自设计文档 §1（前 10% / 30% / 其他，选填）；加分值 AI 草拟，需顾问确认","input":["undergrad_tier","gpa_percent","class_rank"],"undergrad_tier_values_notes":"取值与问卷 seed/questionnaire 的 undergrad_tier 一致：c9 / 985 / 211 / double_first_class / non_key（双非）/ overseas（海本），对应 seed/cn-university 的 C9 / 985 / 211 / 双一流 / 双非；unknown（搜不到）按 non_key 计算（M0-04 约定）。海本 GPA 换算口径另定"},"major_relevance":{"formula":"max(0, level_score[major_relevance] - prereq_penalty * min(missing_prereq_count, prereq_penalty_max_count))","level_score":{"same":100,"related":70,"cross":35},"prereq_penalty":10,"prereq_penalty_max_count":3,"notes":"三档与「缺先修课记风险项」来自设计文档 §1；分值与扣分 AI 草拟，需顾问确认。缺先修课同时输出风险提示","input":["major_relevance","missing_prereq_count"]},"test_scores":{"formula":"按 std_test_type 取一种：gre → clamp(60 + gre_slope * (std_test_total - gre_reference))；gmat_focus → clamp(60 + gmat_slope * (std_test_total - gmat_focus_reference))；gmat_classic → clamp(60 + gmat_slope * (std_test_total - gmat_classic_reference))；未考 → missing_score","gre_reference":320,"gre_slope":4.0,"gmat_focus_reference":645,"gmat_classic_reference":680,"gmat_slope":0.4,"missing_score":30,"not_required_policy":"renormalize","notes":"设计文档 §1：相对目标专业录取中位数的位置，不要求的项目不计入（not_required_policy=renormalize：该项目去掉此维度、其余权重按比例放大）。参考中位数、斜率、未考时的子分均为 AI 草拟，需顾问确认；GMAT Focus 与旧版不互换，分别给参考值（与问卷 std_test_type 一致）","input":["std_test_type","std_test_total"]},"research":{"formula":"research_level = none 时取 none_score；否则 min(100, max(none_score, level_score[research_level] * relevance_factor[research_relevant]) + extra_item_bonus * (research_count - 1))","level_score":{"core_journal":90,"conference":75,"lab_project":55,"none":20},"relevance_factor":{"yes":1.0,"no":0.5},"none_score":20,"extra_item_bonus":5,"notes":"级别（核心期刊 / 会议 / 课题组 / 无）与「按相关度加权」来自设计文档 §1；问卷只采集最高级别、段数、是否相关；分值与系数 AI 草拟，需顾问确认","input":["research_level","research_count","research_relevant"]},"work_experience":{"formula":"none_score + (100 - none_score) * min(effective_months / saturation_months, 1)；effective_months = work_months * company_factor[work_company_tier] * relevance_factor[work_relevant]；无经历时 effective_months = 0","company_factor":{"top":1.0,"normal":0.7},"relevance_factor":{"yes":1.0,"no":0.5},"none_score":20,"saturation_months":12,"saturation_months_by_field":{"business":24,"stem":6},"notes":"头部 / 一般、相关 / 不相关、累计月数来自设计文档 §1；问卷按整体采集（累计月数、是否在头部公司、是否相关）；系数与“满分所需月数”AI 草拟，需顾问确认","input":["work_months","work_company_tier","work_relevant"]},"other_soft":{"formula":"awards_level = none 时取 none_score；否则 min(100, level_score[awards_level] + extra_item_bonus * (awards_count - 1))","level_score":{"international":90,"national":75,"provincial":60,"school":45,"none":20},"none_score":20,"extra_item_bonus":5,"notes":"国际 / 国家 / 省级 / 校级来自设计文档 §1；分值 AI 草拟，需顾问确认","input":["awards_level","awards_count"]},"course_match":{"formula":"clamp(100 * course_match_ratio)","applies":false,"notes":"设计文档 §8（德国）：已对口学分 / 目标项目要求学分，由成绩单解析得到；映射方式 AI 草拟，需顾问确认","input":["course_match_ratio"]}},"hard_thresholds":{"source_priority":["program_requirement","defaults_below"],"on_fail":"needs_improvement","on_fail_label":"补足后可申","unverified_flag_when_default_used":true,"notes":"设计文档 §3：先按项目官网要求过滤，不达标的不进冲稳保，单列「补足后可申」。项目库（abr_requirement）有记录时只用项目库；下列默认值只在项目缺记录时兜底，并给结果打「要求待核实」标记","language":{"scale":"ielts_equivalent","defaults_by_difficulty":{"D1":{"overall":7.0,"min_sub":6.5},"D2":{"overall":7.0,"min_sub":6.0},"D3":{"overall":6.5,"min_sub":6.0},"D4":{"overall":6.5,"min_sub":6.0},"D5":{"overall":6.0,"min_sub":5.5}},"notes":"检查总分与小分（设计文档 §3）；托福 / 多邻国按官方对照表换算