,"D2":{"t":84,"description":"很难（参考：约前 11–30 名院校，或前 10 院校的非热门项目）"},"D3":{"t":78,"description":"中等（参考：约前 31–60 名院校）"},"D4":{"t":72,"description":"较易（参考：约前 61–100 名院校）"},"D5":{"t":64,"description":"容易 / 门槛低（参考：100 名以后或录取较宽松的项目）"}},"notes":"设计文档 §4、§7：冷启动期 T 由顾问按经验给的难度分（五档）决定，每条 T 标明来源；下列各档 T 值与档位说明为 AI 草拟，需顾问确认；排名区间只是帮助顾问定档的参考，不是对任何真实院校的判断"},"portfolio":{"default_mix":{"reach":2,"match":4,"safety":2},"constraints":["total_budget_within_limit","at_least_one_safety_in_first_choice_country"],"notes":"设计文档 §5：默认 2 冲 + 4 稳 + 2 保，总预算不超、至少一所保底在首选国家"},"preference":{"dimensions":["budget","rank_or_employment","city","duration"],"importance":{"high":2,"normal":1},"importance_notes":"问卷 priority_top2：选中的项为 high、未选为 normal（问卷草案「被选 = 高、未选 = 普通」）；分值 AI 草拟，需顾问确认","budget_buckets_wan":{"lt20":20,"20_40":40,"40_60":60,"60_100":100,"gt100":null,"unlimited":null},"budget_notes":"问卷 budget_total 各档的上限（万元人民币，null 为不限）；项目全程费用 = 学费 × 学制年数 × 汇率 + 月生活费 × 学制月数，超出上限的项目不进推荐组合（设计文档 §5「总预算不超」）","cost":{"fx_to_cny":{"USD":7.2,"CNY":1},"living_cny_per_month":15000},"cost_notes":"汇率与月生活费为 AI 草拟的粗略值，需顾问确认并定期按实际汇率更新；项目币种不在表中或缺学费、学制时费用记为未知（不排除，只提示）","ranking_list":"QS","ranking_points":[[1,100],[10,95],[50,85],[100,70],[200,50],[500,25],[1000,5]],"ranking_notes":"「排名优先 / 都看重」时按院校在该榜单最新一年的名次折线换算 0–100；院校库没有名次时不计这一项；AI 草拟，需顾问确认","employment_notes":"院校库暂无就业数据：学生选「就业优先」时这一项不计分，并提示顾问","metropolis_cities":["New York","纽约","Los Angeles","洛杉矶","San Francisco","旧金山","Boston","波士顿","Chicago","芝加哥","Seattle","西雅图","Washington","华盛顿"],"city_notes":"问卷 city_preference：院校所在城市在列表中为「国际大都市」，否则为「大学城 / 中小城市」；城市列表 AI 草拟，需顾问确认","duration_points":[[9,100],[12,100],[18,70],[24,40],[36,20]],"duration_notes":"学制（月）折线换算 0–100，越短分越高；AI 草拟，需顾问确认","notes":"设计文档 §5：每档内按「偏好匹配分」排序（预算、排名 vs 就业、城市、学制，重要程度由学生选择）；偏好只影响排序和组合，不进综合分"},"gap_analysis":{"target":"match","target_p":0.35,"changeable":["language","test_scores","research","work_experience"],"actions":[{"code":"ielts_plus_0_5","dimension":"language","min_months":2},{"code":"gre_plus_10","dimension":"test_scores","min_months":2},{"code":"add_lab_research","dimension":"research","min_months":4},{"code":"add_related_internship_3m","dimension":"work_experience","min_months":3}],"notes":"设计文档 §6：对冲刺校反算进入主攻档所需最小提升，只在可改变的维度里找，并按剩余时间判断是否现实；各动作所需月数 AI 草拟，需顾问确认","application_lead_months":6,"application_lead_notes":"差距反算判断「来得及」：所选动作所需月数之和 ≤ 距入学月数 − 递交提前量；提前量 6 个月为 AI 草拟，需顾问确认"},"calibration":{"refit_min_samples_per_country":200,"seasonal_check":{"safety_admit_rate_min":0.7,"match_admit_rate_range":[0.35,0.7],"reach_admit_rate_max":0.35},"deviation_alert":0.1,"notes":"设计文档 §7：约 200 条结果后用逻辑回归重拟合；每季对比各档实际录取率。偏差告警 0.10 为 AI 草拟，需顾问确认"},"country_rules":{"soft_background_emphasis":{"value":true,"notes":"设计文档 §8：软背景权重高（体现在 weights 中实习 / 科研 / 其他软背景占比高于英澳）"},"conservative_tiering":{"t_offset_applied":true,"notes":"设计文档 §8：不确定性大、档位偏保守 → a 取小值，并在 probability.t_offset 统一抬高参考线；幅度 AI 草拟，需顾问确认"},"test_policy":{"per_program":true,"notes":"设计文档 §1、§8：标化政策因校而异；项目不要求时按 scoring.test_scores.not_required_policy 处理"},"undergraduate_model":{"separate_config":"US_BACHELOR（不在本批）","notes":"设计文档 §8：本科与研究生分开建模；本科为综合评估，冷启动最后上线"},"notes":"设计文档 §8 多国家适配"}}$ejson$)
) as v(config_code, country, degree, version, file_status, config)
on conflict (config_code, version) where del_flag = '0'
do update set country     = excluded.country,
              degree      = excluded.degree,
              file_status = excluded.file_status,
              config      = excluded.config,
              update_by   = 'admin',
              update_time = now()
        where abr_engine_config.publish_status = 'draft'
          and abr_engine_config.config is distinct from excluded.config;
